void twoSum(vector<int>& a, int t) {
    unordered_map<int,int> idx;
    for (int i = 0; i < (int)a.size(); i++) {
        auto it = idx.find(t - a[i]);
        if (it != idx.end()) { cout << it->second << ' ' << i; return; }
        idx[a[i]] = i;
    }
}

