void mostFrequent(vector<int> a) {
    unordered_map<int,int> cnt;
    for (int x : a) cnt[x]++;
    int best = 0, mode = a[0];
    for (auto& [v, c] : cnt)
        if (c > best) { best = c; mode = v; }
    cout << mode << ' ' << best;
}

